import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import os
import numpy as np

# Set seaborn style for better looking charts
sns.set_theme(style="whitegrid")

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

# Read data
df = pd.read_csv('/app/benchmark/data.csv')

# --- 1. Market Overview ---
total_books_appearances = len(df)
unique_books = df['Name'].nunique()
genre_split = df['Genre'].value_counts()
avg_price_total = df['Price'].mean()
avg_rating_total = df['User Rating'].mean()
avg_reviews_total = df['Reviews'].mean()

# --- 2. Price vs. Rating Correlation ---
correlation = df['Price'].corr(df['User Rating'])

fig, ax = plt.subplots(figsize=(8, 5))
sns.regplot(data=df, x='Price', y='User Rating', scatter_kws={'alpha':0.5}, line_kws={'color':'red'}, ax=ax)
ax.set_title('Price vs. User Rating')
ax.set_xlabel('Price ($)')
ax.set_ylabel('User Rating')
chart_corr = fig_to_base64(fig)

# --- 3. Genre Comparison ---
genre_stats = df.groupby('Genre').agg({
    'Price': 'mean',
    'User Rating': 'mean',
    'Reviews': 'mean',
    'Name': 'count'
}).rename(columns={'Name': 'Total Appearances'}).round(2)

fig, axes = plt.subplots(1, 3, figsize=(15, 5))
sns.barplot(data=df, x='Genre', y='Price', ax=axes[0], palette='muted', errorbar=None)
axes[0].set_title('Average Price by Genre')
axes[0].set_ylabel('Price ($)')

sns.barplot(data=df, x='Genre', y='User Rating', ax=axes[1], palette='muted', errorbar=None)
axes[1].set_title('Average Rating by Genre')
axes[1].set_ylabel('User Rating')
axes[1].set_ylim(4.0, 5.0)

sns.barplot(data=df, x='Genre', y='Reviews', ax=axes[2], palette='muted', errorbar=None)
axes[2].set_title('Average Reviews by Genre')
axes[2].set_ylabel('Review Count')
plt.tight_layout()
chart_genre = fig_to_base64(fig)

# --- 4. Temporal Trends (2009-2019) ---
yearly_stats = df.groupby('Year').agg({
    'Price': 'mean',
    'User Rating': 'mean'
}).reset_index()

genre_yearly_price = df.groupby(['Year', 'Genre'])['Price'].mean().reset_index()

fig, ax1 = plt.subplots(figsize=(10, 5))
sns.lineplot(data=df, x='Year', y='Price', hue='Genre', marker='o', ax=ax1, errorbar=None)
ax1.set_title('Average Price Trend by Genre (2009-2019)')
ax1.set_ylabel('Average Price ($)')
ax1.set_xticks(range(2009, 2020))
chart_trend_price = fig_to_base64(fig)

fig, ax2 = plt.subplots(figsize=(10, 5))
sns.lineplot(data=df, x='Year', y='User Rating', hue='Genre', marker='o', ax=ax2, errorbar=None)
ax2.set_title('Average User Rating Trend by Genre (2009-2019)')
ax2.set_ylabel('Average Rating')
ax2.set_xticks(range(2009, 2020))
chart_trend_rating = fig_to_base64(fig)


# --- 5. Top Authors ---
author_counts = df['Author'].value_counts().head(10)
top_authors_df = df[df['Author'].isin(author_counts.index)]
author_stats = top_authors_df.groupby('Author').agg({
    'Name': 'count',
    'Price': 'mean',
    'User Rating': 'mean'
}).rename(columns={'Name': 'Appearances'}).sort_values(by='Appearances', ascending=False).round(2)

fig, ax = plt.subplots(figsize=(10, 5))
sns.barplot(x=author_counts.values, y=author_counts.index, palette='viridis', ax=ax)
ax.set_title('Top 10 Authors by Bestseller Appearances')
ax.set_xlabel('Number of Appearances')
chart_authors = fig_to_base64(fig)

